namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments = new()
    {
        new Department { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new Department { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new Department { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new Department { Id = 4, Name = "English", Abbreviation = "ENG" },
        new Department { Id = 5, Name = "History", Abbreviation = "HIST" }
    };

    private readonly List<Course> _courses = new()
    {
        new Course
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.",
            Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on programming pedagogy."
        },
        new Course
        {
            Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.",
            Credits = 4, Schedule = "TTh 10:30–11:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and has contributed to open-source projects in computational geometry."
        },
        new Course
        {
            Id = 3, CourseCode = "CS 330", Title = "Database Systems",
            Description = "Covers relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.",
            Credits = 3, Schedule = "MWF 1:00–1:50 PM", DepartmentId = 1, IsFeatured = false,
            InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on programming pedagogy."
        },
        new Course
        {
            Id = 4, CourseCode = "MATH 151", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
            Credits = 4, Schedule = "MWF 8:00–8:50 AM", DepartmentId = 2, IsFeatured = true,
            InstructorName = "Prof. Diana Reyes", InstructorBio = "Prof. Reyes is an award-winning educator whose research focuses on applied mathematics and mathematical modeling."
        },
        new Course
        {
            Id = 5, CourseCode = "MATH 252", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.",
            Credits = 3, Schedule = "TTh 1:00–2:20 PM", DepartmentId = 2, IsFeatured = false,
            InstructorName = "Dr. Eric Johansson", InstructorBio = "Dr. Johansson's research covers numerical linear algebra and high-performance computing."
        },
        new Course
        {
            Id = 6, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions for hands-on experimentation.",
            Credits = 4, Schedule = "MWF 10:00–10:50 AM, Lab: F 2:00–4:00 PM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Dr. Frank Okafor", InstructorBio = "Dr. Okafor is an experimental physicist with expertise in condensed matter physics and science education outreach."
        },
        new Course
        {
            Id = 7, CourseCode = "PHYS 220", Title = "Electromagnetism",
            Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",
            Credits = 4, Schedule = "TTh 9:00–10:20 AM", DepartmentId = 3, IsFeatured = true,
            InstructorName = "Dr. Grace Liu", InstructorBio = "Dr. Liu researches photonics and has authored over 50 papers on electromagnetic wave propagation."
        },
        new Course
        {
            Id = 8, CourseCode = "ENG 110", Title = "College Writing",
            Description = "Develops skills in academic writing, critical reading, argumentation, and research methods.",
            Credits = 3, Schedule = "MWF 11:00–11:50 AM", DepartmentId = 4, IsFeatured = false,
            InstructorName = "Prof. Hannah Kim", InstructorBio = "Prof. Kim is a published author and writing instructor with a focus on composition theory and rhetoric."
        },
        new Course
        {
            Id = 9, CourseCode = "ENG 250", Title = "American Literature",
            Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and society.",
            Credits = 3, Schedule = "TTh 2:30–3:50 PM", DepartmentId = 4, IsFeatured = false,
            InstructorName = "Dr. Ian Patel", InstructorBio = "Dr. Patel specializes in 20th-century American fiction and has published extensively on multicultural narratives."
        },
        new Course
        {
            Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "Explores the development of civilizations from prehistory through the late medieval period, covering political, social, and cultural history.",
            Credits = 3, Schedule = "MWF 2:00–2:50 PM", DepartmentId = 5, IsFeatured = false,
            InstructorName = "Dr. Julia Santos", InstructorBio = "Dr. Santos is a historian of the ancient world with fieldwork experience in Mediterranean archaeology."
        },
        new Course
        {
            Id = 11, CourseCode = "HIST 305", Title = "Modern European History",
            Description = "Examines European political, intellectual, and social history from the Enlightenment to the present day.",
            Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", DepartmentId = 5, IsFeatured = true,
            InstructorName = "Prof. Karl Weber", InstructorBio = "Prof. Weber is a specialist in modern European intellectual history and has authored three books on political thought."
        }
    };

    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

